const rawMd = $input.first().json?.markdown \vert{}\vert{} '';
const triggerData = $('Execute Workflow Trigger').first().json;
return [{
  json: {
    url: triggerData.url,
    category: triggerData.category,
    site_name: triggerData.site_name,
    country: triggerData.country || 'US',
    keyword: triggerData.keyword,
    truncated_markdown: rawMd.substring(0, 30000)
  }
}];

const firstItem = $input.first().json;
const rawText = firstItem.text \vert{}\vert{} firstItem.output \vert{}\vert{} firstItem.response \vert{}\vert{} '[]';
const meta =$('마크다운 길이 제한 (토큰 보호)').first().json || {};
const parentUrl = meta.url || '';
let urls = [];
try {
  const match = String(rawText).match(/\[[\s\S]*\]/);
  const jsonStr = match ? match[0] : String(rawText).trim();
  const parsed = JSON.parse(jsonStr);
  urls = Array.isArray(parsed) ? parsed : (parsed.urls || parsed.links || []);
} catch (e) { urls = []; }
const uniqueUrls = [...new Set(urls.filter(u => typeof u === 'string' && u.startsWith('http')))];
return uniqueUrls.map(detailUrl => ({
  json: {
    url: detailUrl,
    detail_url: detailUrl,
    category: meta.category || 'E-commerce',
    site_name: meta.site_name || '',
    country: meta.country || 'US',
    parent_url: parentUrl
  }
}));

